// Período fechado: mês anterior ao da execução
const hoje = new Date();
const inicio = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
const fim = new Date(hoje.getFullYear(), hoje.getMonth(), 0);
const iso = (d) => d.toISOString().slice(0, 10);
return [{ json: { period_start: iso(inicio), period_end: iso(fim) } }];

// Agrupa os apontamentos por contrato e monta o payload do itsm-bridge.
// O vínculo chamado -> contrato vem do campo customizado/entidade do GLPI.
const periodo = $('Calcula o período').first().json;
const porContrato = new Map();

for (const item of $input.all()) {
  const t = item.json;
  const contratoId = t.contract_id || t['80'] || 'SEM-CONTRATO';
  if (!porContrato.has(contratoId)) porContrato.set(contratoId, []);
  porContrato.get(contratoId).push({
    ticket_id: Number(t['2'] ?? t.tickets_id ?? 0),
    minutes: Math.round(Number(t['5'] ?? t.actiontime ?? 0) / 60),
    billable: true,
    performed_at: (t['4'] ?? periodo.period_start).slice(0, 10),
  });
}

return [...porContrato.entries()].map(([contrato, entradas]) => ({
  json: {
    contract_id: contrato,
    period_start: periodo.period_start,
    period_end: periodo.period_end,
    time_entries: entradas,
  },
}));
